$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

$root = (Get-Location).Path
if (-not (Test-Path (Join-Path $root 'pubspec.yaml'))) {
    throw 'Run this script from the almustafa-connect-erp project root.'
}

$utf8 = New-Object System.Text.UTF8Encoding($false)
$stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
$backupRoot = Join-Path `
    (Split-Path $root -Parent) `
    "almustafa-connect-erp_backups/user_accounts_management_$stamp"

function Read-ProjectFile {
    param([Parameter(Mandatory = $true)][string]$RelativePath)

    $path = Join-Path $root $RelativePath
    if (-not (Test-Path $path)) {
        throw "Required file not found: $RelativePath"
    }

    return [IO.File]::ReadAllText($path).Replace("`r`n", "`n")
}

function Write-ProjectFile {
    param(
        [Parameter(Mandatory = $true)][string]$RelativePath,
        [Parameter(Mandatory = $true)][string]$Content
    )

    $path = Join-Path $root $RelativePath
    New-Item `
        -ItemType Directory `
        -Path (Split-Path $path -Parent) `
        -Force | Out-Null

    [IO.File]::WriteAllText($path, $Content, $utf8)
    Write-Host "Created/updated: $RelativePath" -ForegroundColor Green
}

function Backup-ProjectFile {
    param([Parameter(Mandatory = $true)][string]$RelativePath)

    $source = Join-Path $root $RelativePath
    if (-not (Test-Path $source)) { return }

    $destination = Join-Path $backupRoot $RelativePath
    New-Item `
        -ItemType Directory `
        -Path (Split-Path $destination -Parent) `
        -Force | Out-Null

    Copy-Item $source $destination -Force
}

function Add-Import {
    param(
        [Parameter(Mandatory = $true)][string]$Content,
        [Parameter(Mandatory = $true)][string]$ImportLine
    )

    if ($Content.Contains($ImportLine)) {
        return $Content
    }

    $matches = [regex]::Matches(
        $Content,
        "(?m)^import\s+['""].+?['""];\s*$"
    )

    if ($matches.Count -eq 0) {
        throw "Import block not found: $ImportLine"
    }

    $last = $matches[$matches.Count - 1]
    return $Content.Insert(
        $last.Index + $last.Length,
        "`n$ImportLine"
    )
}

$payloads = @{
    'functions/package.json' = ''
    'functions/index.js' = ''
    'lib/features/access_control/domain/entities/user_account_entity.dart' = ''
    'lib/features/access_control/domain/services/user_account_service.dart' = ''
    'lib/features/access_control/data/services/user_account_service_impl.dart' = ''
    'lib/features/access_control/presentation/pages/user_accounts_management_page.dart' = ''
    'docs/user_accounts_management_deployment.md' = ''
}
$pubspec = 'pubspec.yaml'
$firebaseJson = 'firebase.json'
$rolesPage =
    'lib/features/access_control/presentation/pages/roles_permissions_page.dart'

foreach ($path in (@(
    $pubspec,
    $firebaseJson,
    $rolesPage
) + $payloads.Keys)) {
    Backup-ProjectFile -RelativePath $path
}

foreach ($entry in $payloads.GetEnumerator()) {
    $content = [Text.Encoding]::UTF8.GetString(
        [Convert]::FromBase64String($entry.Value)
    )
    Write-ProjectFile `
        -RelativePath $entry.Key `
        -Content $content
}

# Add Flutter callable-functions dependency.
$content = Read-ProjectFile -RelativePath $pubspec

if (-not $content.Contains('cloud_functions:')) {
    $anchor = '  cloud_firestore: ^6.0.1'

    if (-not $content.Contains($anchor)) {
        throw 'cloud_firestore dependency anchor not found in pubspec.yaml.'
    }

    $content = $content.Replace(
        $anchor,
        "$anchor`n  cloud_functions: ^6.0.1"
    )
}

Write-ProjectFile -RelativePath $pubspec -Content $content

# Add Cloud Functions source configuration while preserving existing config.
$firebasePath = Join-Path $root $firebaseJson
$firebaseConfig = Get-Content $firebasePath -Raw | ConvertFrom-Json

$hasFunctions =
    $firebaseConfig.PSObject.Properties.Name -contains 'functions'

if (-not $hasFunctions) {
    $firebaseConfig | Add-Member `
        -NotePropertyName 'functions' `
        -NotePropertyValue ([pscustomobject]@{
            source = 'functions'
        })
} else {
    $functionConfig = $firebaseConfig.functions

    if ($functionConfig -is [System.Array]) {
        # Preserve existing multi-codebase configuration.
    } elseif (
        -not (
            $functionConfig.PSObject.Properties.Name -contains 'source'
        )
    ) {
        $functionConfig | Add-Member `
            -NotePropertyName 'source' `
            -NotePropertyValue 'functions'
    } else {
        $functionConfig.source = 'functions'
    }
}

$firebaseContent =
    $firebaseConfig | ConvertTo-Json -Depth 30

Write-ProjectFile `
    -RelativePath $firebaseJson `
    -Content ($firebaseContent + "`n")

# Add navigation from Roles & Permissions.
$content = Read-ProjectFile -RelativePath $rolesPage

$content = Add-Import `
    -Content $content `
    -ImportLine "import 'user_accounts_management_page.dart';"

if (-not $content.Contains('const UserAccountsManagementPage()')) {
    $actionsMatch = [regex]::Match(
        $content,
        '(?m)^\s*actions:\s*\[\s*$'
    )

    if (-not $actionsMatch.Success) {
        throw 'Roles & Permissions AppBar actions anchor not found.'
    }

    $indent = [regex]::Match(
        $actionsMatch.Value,
        '^\s*'
    ).Value

    $button = @"
$indent  TextButton.icon(
$indent    onPressed: () {
$indent      Navigator.of(context).push<void>(
$indent        MaterialPageRoute<void>(
$indent          builder: (_) =>
$indent              const UserAccountsManagementPage(),
$indent        ),
$indent      );
$indent    },
$indent    icon: const Icon(Icons.person_add_alt_1),
$indent    label: const Text('User Accounts'),
$indent  ),
"@

    $content = $content.Insert(
        $actionsMatch.Index + $actionsMatch.Length,
        "`n$button"
    )
}

Write-ProjectFile `
    -RelativePath $rolesPage `
    -Content $content

Write-Host ''
Write-Host 'Running flutter pub get...' -ForegroundColor Cyan

& flutter pub get

if ($LASTEXITCODE -ne 0) {
    throw 'flutter pub get failed.'
}

Write-Host ''
Write-Host 'Running dart format...' -ForegroundColor Cyan

& dart format `
    'lib/features/access_control/domain/entities/user_account_entity.dart' `
    'lib/features/access_control/domain/services/user_account_service.dart' `
    'lib/features/access_control/data/services/user_account_service_impl.dart' `
    'lib/features/access_control/presentation/pages/user_accounts_management_page.dart' `
    $rolesPage

if ($LASTEXITCODE -ne 0) {
    throw 'dart format failed.'
}

if (Get-Command npm -ErrorAction SilentlyContinue) {
    Write-Host ''
    Write-Host 'Installing Cloud Functions packages...' -ForegroundColor Cyan

    Push-Location (Join-Path $root 'functions')
    try {
        & npm install

        if ($LASTEXITCODE -ne 0) {
            throw 'npm install failed inside functions folder.'
        }

        & npm run lint

        if ($LASTEXITCODE -ne 0) {
            throw 'Cloud Functions JavaScript validation failed.'
        }
    } finally {
        Pop-Location
    }
} else {
    Write-Host ''
    Write-Host 'npm was not found. Install Node.js 20, then run npm install inside functions.' -ForegroundColor Yellow
}

Write-Host ''
Write-Host 'Running flutter analyze...' -ForegroundColor Cyan

& flutter analyze

if ($LASTEXITCODE -ne 0) {
    throw 'flutter analyze found issues. Copy the complete output into ChatGPT.'
}

Write-Host ''
Write-Host 'User Accounts Management secure core setup completed successfully.' -ForegroundColor Green
Write-Host 'Cloud Functions were created but NOT deployed.' -ForegroundColor Yellow
Write-Host 'Deploy after verifying your Super Admin assignment.' -ForegroundColor Yellow
Write-Host 'Command: firebase deploy --only functions' -ForegroundColor Cyan
Write-Host 'Guide: docs/user_accounts_management_deployment.md' -ForegroundColor Cyan
Write-Host "Backup: $backupRoot" -ForegroundColor DarkGray
